import { onLCP, onINP, onCLS } from 'web-vitals';

const report = (metric) =>
  navigator.sendBeacon('/analytics', JSON.stringify({
    name: metric.name,
    value: metric.value,
    id: metric.id,
  }));

onLCP(report);
onINP(report);
onCLS(report);

async function processAll(items) {
  for (const item of items) {
    process(item);
    // give the browser a chance to handle input and paint
    await scheduler.yield();
  }
}

// thrashing: write, then read, on every iteration
for (const el of items) {
  el.style.width = '100px';
  console.log(el.offsetWidth); // forces layout
}

const start = Math.floor(scrollTop / rowHeight);
const end = start + visibleCount;
const rows = items.slice(start, end);

return (
  <div style={{ height: items.length * rowHeight }}>
    {rows.map((row, i) => (
      <Row key={row.id} style={{ top: (start + i) * rowHeight }} {...row} />
    ))}
  </div>
);
